#!/usr/bin/env python3
"""Five-page course proposal from accepted common-input native-3D evidence."""
import json
from xml.sax.saxutils import escape
from build_proposal import Doc,ROOT,OUT

class Paper(Doc):
 def table(self,rows,widths):
  s='<w:tbl><w:tblPr><w:tblW w:w="9906" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="8" w:color="37606C"/><w:bottom w:val="single" w:sz="8" w:color="37606C"/></w:tblBorders><w:tblCellMar><w:top w:w="65" w:type="dxa"/><w:bottom w:w="65" w:type="dxa"/><w:left w:w="90" w:type="dxa"/><w:right w:w="90" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>'+''.join(f'<w:gridCol w:w="{w}"/>' for w in widths)+'</w:tblGrid>'
  for i,row in enumerate(rows):
   s+='<w:tr><w:trPr><w:cantSplit/></w:trPr>'
   for text,w in zip(row,widths):
    border='<w:tcBorders><w:bottom w:val="single" w:sz="5" w:color="809BA3"/></w:tcBorders>' if i==0 else ''
    s+=f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/>{border}</w:tcPr><w:p><w:pPr><w:spacing w:after="15" w:line="220" w:lineRule="auto"/></w:pPr><w:r><w:rPr><w:sz w:val="20"/>'+('<w:b/>' if i==0 else '')+f'</w:rPr><w:t>{escape(str(text))}</w:t></w:r></w:p></w:tc>'
   s+='</w:tr>'
  self.parts.append(s+'</w:tbl>');self.p('',size=4)

NAMES={'pp':'PP + static guard','rpp':'RPP-inspired','distance':'Distance yield','forecast_static':'Zero-velocity forecast','forecast':'Velocity forecast','dwa':'DWA-style'}

def build():
 B=ROOT/'outputs/classical';e=json.loads((B/'test/summary.json').read_text());ce=json.loads((B/'encounter_test/summary.json').read_text());v=json.loads((ROOT.parents[2]/'storage_management/ucmp_week3_classical_baselines_20261102-104447/video_acceptance.json').read_text())
 rows={x['method']:x for x in e['summary'] if x['density']=='all'};f=rows['forecast'];r=rows['rpp'];z=rows['forecast_static'];n=f['valid'];assert all(x['valid']==n and x['requested']==20 for x in rows.values())
 for name,count in [('random_test_acceptance',120),('encounter_test_acceptance',40)]:
  receipt=json.loads((ROOT.parents[2]/'storage_management/ucmp_week3_classical_baselines_20261102-104447'/f'{name}.json').read_text());assert receipt['passed'] and receipt['episodes']==count and receipt['frozen_sources_verified']
 mission=next(x for x in v['checks'] if x['name']=='inspection_forecast');assert mission['inspection_complete']
 pair=lambda control:next(x for x in e['paired'] if x['control']==control and x['method']=='forecast')
 d=Paper();d.p('When does short-horizon prediction help robots share urban pavements?','Title');d.p('A mini research proposal with a common-input three-dimensional pilot',size=23);d.p('UCMP-MB · Week 3 · Option 1 · Individual assignment · 2 November 2026','Caption')
 d.p('1. Research question, theory and urban relevance','Heading')
 d.p('Does a small, route-conditioned pedestrian-velocity module improve contact-free arrival or reduce unnecessary waiting compared with classical controllers that have the same route and state information? The application is a service robot travelling to a street-inspection waypoint, stopping and recording a view. The question concerns the conditions under which prediction helps, rather than a claim to outperform all navigation systems.')
 d.p('Urban pavements support movement, access and social interaction. A robot completing its task can still obstruct a crossing or pass uncomfortably close to people. Social-navigation evaluation therefore distinguishes physical safety, comfort, predictability and context [2]. Here, geometric distance is an observable interaction proxy; it cannot establish comfort. The urban-informatics lens is the link between spatial measurement and an operational decision: how arrival, clearance and encounter duration are defined can change which controller appears preferable.')
 d.image(B/'figures/mission_scene_pair.png')
 d.p('Figure 1. Actual native MetaUrban RGB, not a schematic: departure and the captured view after strict arrival and a physical stop (development seed 902, 15 pedestrians). The final one-second speed remained below 0.1 m/s, with no recorded contact. Images document the task; all controllers use numerical states, not RGB.','Caption')
 d.p('The contribution is a transparent, training-free pilot in a three-dimensional shared streetscape [1]. A previous PPO comparison mixed route correction with risk prediction. The present study replaces that nominal driver with a common path tracker and tests RPP-inspired [4] and DWA-style [5] controls. These are explicitly adapted implementations, not official ROS/Nav2 reproductions or a state-of-the-art benchmark.')
 d.page();d.p('2. Data, spatial units and outcome validity','Heading')
 d.p('The data are synthetic ego/pedestrian trajectories, executed actions, native contact flags, reference routes and RGB from MetaUrban [1], pinned to source commit 6b8ff9a. Existing public tiny assets are imported offline with hashes. Coordinates are local metres, without a geographic reference system or sampled urban population. One 0.1 s decision is the observation unit, one episode the outcome unit, and scene seed × crowd size the paired condition. Scene seed clusters the two crowd conditions.')
 d.p('Table 1. Common simulation and data contract.','Caption')
 d.table([['Element','Specification'],['Street / crowd','One generated X-intersection family; sidewalks, crossings and furniture; object-density setting 0.3; 5 or 15 people, not persons/m²'],['Ego / information','Native wheelchair-shaped agent with four-wheel Bullet dynamics; full route, exact ego state, current pedestrian poses/derived velocities and static object boxes'],['Time / actuation','Forward-only; 3 m/s cruise ceiling; shared steering-rate limit; finite wheel braking; 600 decisions / 60 s; no ego teleportation'],['Development / fresh test','Seeds 900–903: 48 development runs. Frozen seeds 300–309 × 2 crowds × 6 methods: 120 requested fresh runs'],['Separate diagnostics','Crossing, receding, approaching and stationary single pedestrians; development seed 902; fresh seeds 320–321: 40 runs across 5 methods']],[2250,7656])
 d.p('A strict arrival requires BOTH the native arrival flag and endpoint distance ≤2 m. The native >95% route-progress rule alone can end metres before the waypoint; an earlier audit also found coincident start/goal tasks. Route length and start-to-endpoint distance must therefore both be ≥5 m before any control step. Invalid tasks are retained without replacement, and all failures remain in the denominator of valid tasks. Native arrival is logged separately.')
 d.p('Pedestrian contact uses raw crash_human OR crash_vehicle: native SimplePedestrian collision bodies are vehicle-tagged, and other moving traffic is disabled here. Any-contact-free arrival also excludes static-object, building and sidewalk contacts. Proximity exposure is the fraction of observed episode time with a planar native-box gap <1 m, sampled at 0.1 s. It is not the legacy circle proxy, continuous swept clearance, or a comfort measurement. Episodes above 20 m/s are flagged and retained.')
 d.p('In the diagnostic suite, one native pedestrian follows a prescribed x₀ + tv trajectory in the actual street; only that pedestrian pose is scripted. The controller sees current poses and derived velocities, never the future recipe. Ego dynamics remain native. These mechanistic tests are reported separately from random streets and do not model responsive human behaviour.')
 d.page();d.p('3. Methods, comparison logic and analysis','Heading')
 d.p('Every method receives the same information and uses one pure-pursuit reference tracker [3], the same actuator limits and a common one-second static-object footprint guard. This controls route knowledge and basic static protection. No neural policy is loaded or trained. RPP and DWA already address related path-following and obstacle-avoidance problems [4,5]; this pilot asks what a small predictive module adds within the stated interface.')
 d.p('Table 2. Implemented local adaptations and ablations.','Caption')
 d.table([['Method','Control mechanism'],['PP + static guard','Pure pursuit with speed limited near the endpoint; no pedestrian yielding'],['RPP-inspired','Curvature/proximity speed regulation and a one-second fixed-curvature footprint check against current pedestrian occupancy'],['Distance yield','The same regulated route tracking; speed scaled by current pedestrian box gap between 0.25 and 1.5 m'],['Zero-velocity forecast','Route-following candidate-speed rollouts, but pedestrian velocity set to zero; isolates the prediction input'],['Velocity forecast','Identical candidate rollouts using measured pedestrian velocity with constant-velocity extrapolation'],['DWA-style','Bounded speed/steering search; scores progress, route deviation, clearance and control change under the same footprint thresholds']],[2400,7506])
 d.p('The forecast module compares the cruise cap, 2, 1, 0.5 and 0 m/s over 1.5 s in 0.1 s increments. A bicycle approximation includes 1.5 m/s² acceleration and 2 m/s² braking; route following is recomputed along each rollout. Native 1.5 × 1 m ego and 1 × 1 m pedestrian planar footprints replace radius-only checks. It selects the highest speed meeting a 0.25 m pedestrian buffer and 0.10 m static buffer, with 0.2 s clear before release. These engineering buffers are not validated personal distances.')
 d.p('Stopping is predicted too: a preplanned pedestrian may walk into a stationary robot. If no candidate meets the buffer and stopping predicts overlap, a moving candidate is allowed only when its worst gap improves by >0.1 m and its static gap passes. Such steps are explicitly marked buffer-infeasible. The approximate prediction, sampled geometry and finite braking provide no safety guarantee. DWA-style additionally searches steering; its Ackermann adaptation is not the original synchro-drive algorithm [5].')
 d.p('Exploratory H1: measured velocity improves contact-free arrival or waiting relative to its zero-velocity ablation. H2: the module provides a useful contact/completion/efficiency trade-off relative to RPP-inspired and DWA-style controls. Code and parameters were frozen before either fresh suite. Report paired rescues/regressions, contact counts, waiting and exposure separately; travel-time differences use jointly successful matched cases. Descriptive 95% percentile intervals resample ten whole scene seeds, retaining both crowds; the small sample does not support rare-event safety claims.')
 d.page();d.p('4. Preliminary evidence from frozen fresh tests','Heading')
 d.p(f'Table 3. Random streets: 20 requested conditions per method, {n} valid and {20-n} rejected by the predeclared task gate. Contacts are episode counts.','Caption')
 table=[['Method',f'Strict / {n}','Ped. contact','Contact-free','Mean wait (s)']]
 for m,name in NAMES.items():
  x=rows[m];table.append([name,x['strict_goals'],x['pedestrian_contacts'],x['contact_free_goals'],f"{x['mean_wait_s']:.1f}"])
 d.table(table,[2850,1500,1600,1800,2156])
 d.image(B/'figures/fresh_outcomes.png')
 d.p('Figure 2. All valid random-street test outcomes under identical initial conditions. Contact-free arrival excludes every recorded contact type; successful contact episodes and failures remain visible in the tables and supplementary condition matrix.','Caption')
 p=pair('rpp');a=pair('forecast_static');w=pair('dwa')
 d.p(f"Against RPP-inspired control, velocity forecasting rescued {p['rescued']} strict-arrival conditions and lost {p['regressed']}; its net change in contact-free arrivals was {p['contact_free_goal_delta']:+d}. Against the zero-velocity ablation, those counts were {a['rescued']}, {a['regressed']} and {a['contact_free_goal_delta']:+d}. Against DWA-style, they were {w['rescued']}, {w['regressed']} and {w['contact_free_goal_delta']:+d}. These comparisons attribute effects to the present implementation and inputs, not to an algorithm family in general.")
 if p['mean_joint_delay_s'] is not None:
  d.p(f"On {p['jointly_successful_n']} jointly successful conditions, forecast minus RPP travel time averaged {p['mean_joint_delay_s']:+.2f} s. Mean box-based near exposure was {100*f['mean_box_near_fraction']:.2f}% versus {100*r['mean_box_near_fraction']:.2f}%. Completion, contacts and exposure must be read together; a controller that waits or ends early changes its exposure denominator.")
 d.p(f"The zero-velocity and measured-velocity versions each produced {f['strict_goals']} strict arrivals, {f['contact_free_goals']} contact-free arrivals and {f['pedestrian_contacts']} pedestrian-contact episodes. H1 is unsupported for these aggregate outcomes. PP plus the common static guard matched the same arrival/contact-free counts with mean waiting {rows['pp']['mean_wait_s']:.2f} s versus {f['mean_wait_s']:.2f} s for forecasting. The pilot therefore does not justify extra predictive complexity as a default. All {sum(x['physical_anomalies'] for x in rows.values())} speed-anomaly episodes remain included.")
 d.p(f"Relative to the zero-velocity ablation, measured velocity added {a['mean_joint_delay_s']:+.2f} s on the same {a['jointly_successful_n']} successful conditions. The efficiency difference from RPP therefore does not establish a benefit from the velocity input itself.")
 d.page();d.p('5. Diagnostic findings and feasible next study','Heading')
 d.p('Table 4. Controlled suite: contact-free strict arrivals / 2 fresh seeds for each encounter. Scripted single pedestrians; never pooled with random-street counts.','Caption')
 kinds=['crossing','receding','approaching','stationary'];methods=['rpp','distance','forecast_static','forecast','dwa'];table=[['Encounter','RPP','Dist.','Zero-v','Forecast','DWA']]
 for kind in kinds:table.append([kind,*[next(x['contact_free_goals'] for x in ce['summary'] if x['density']==kind and x['method']==m) for m in methods]])
 d.table(table,[2450,1400,1400,1500,1756,1400])
 d.p('The crossing tests expose an efficiency–exposure trade-off: forecast waited 0 s versus 1.0 s for RPP-inspired, but mean near exposure was 2.42% versus 0%. All methods completed both receding-person cases without contact. Every speed-only method contacted both approaching pedestrians; DWA-style obtained one contact-free arrival. No method completed either stationary-obstruction task. These diagnostics expose limitations rather than establishing realistic human interaction. Native ORCA-based preplanning [6] and scripted motion do not imply reciprocal responses.')
 d.p('All five path-following variants timed out on seeds 305/306 in both crowds. Moving forecast candidates failed the static buffer while stopping passed. DWA-style reached all four of these conditions, three without contact, but failed six other conditions that forecast completed. This suggests testing conditional lateral alternatives, rather than replacing the tracker everywhere; the static check alone does not prove physical impassability.')
 d.p('The proposed next stage tests a small, currently unimplemented detour trigger: after >3 s stopped by static checks, consider left/right waypoint offsets up to 1.5 m. Candidates must preserve footprint buffers and lie within validated walkable geometry; otherwise keep waiting. H3 is that bounded detours improve strict arrival without reducing contact-free arrival. This adds a spatial alternative rather than simply weakening the buffer.')
 d.p('A feasible design is ten new seeds × two validated layout families × two crowd sizes × three methods (RPP-inspired, forecast, forecast + detour), giving 120 runs. Separate setup scenes will develop the trigger and verify walkable-area checks; sources/settings are then frozen before new seeds. Retain all invalid tasks without replacement, use paired outcomes and cluster scene seeds. Four local stages—setup, freeze, evaluation, failure review—require no neural training. The current evidence favours a simple path follower as default; any detour or predictive benefit remains a hypothesis for the next study.')
 d.p('Limits include privileged exact states, one asset profile/layout family, short tasks, simplified wheel dynamics and planar sampled geometry rather than full mesh collision prediction. Route rollouts also omit steering slew and detailed wheel transients. Neither the wheelchair-shaped embodiment nor a captured image validates a real inspection task. Synthetic data contain no personal observations; future street recording would need consent-aware collection, minimal retention and accessibility review with affected users [2]. This course proposal offers a reproducible comparison and bounded research question, not a real-world safety claim.')
 d.p('References','Heading')
 refs=[
 '[1] Wu, W. et al. (2024). MetaUrban: An Embodied AI Simulation Platform for Urban Micromobility. arXiv:2407.08725. https://arxiv.org/abs/2407.08725',
 '[2] Francis, A. et al. (2023). Principles and Guidelines for Evaluating Social Robot Navigation Algorithms. arXiv:2306.16740. https://arxiv.org/abs/2306.16740',
 '[3] Coulter, R. C. (1992). Implementation of the Pure Pursuit Path Tracking Algorithm. CMU-RI-TR-92-01, Carnegie Mellon University.',
 '[4] Macenski, S., Singh, S., Martin, F. & Gines, J. (2023). Regulated Pure Pursuit for Robot Path Tracking. Autonomous Robots. https://arxiv.org/abs/2305.20026',
 '[5] Fox, D., Burgard, W. & Thrun, S. (1997). The Dynamic Window Approach to Collision Avoidance. IEEE Robotics & Automation Magazine 4(1), 23–33.',
 '[6] van den Berg, J., Guy, S. J., Lin, M. & Manocha, D. (2011). Reciprocal n-body collision avoidance. Robotics Research, 3–19. doi:10.1007/978-3-642-19457-3_1.'
 ]
 for ref in refs:d.p(ref,size=18)
 path=OUT/'Week3_Streetscape_Research_Proposal_v3.docx';assert not path.exists(),'Preserve earlier rendering; choose a new filename for revisions';d.save(path);print(path)

if __name__=='__main__':build()
